// Generated by LB-07 QA Engineer from a plan over a closed vocabulary (goto, click by role and name,
// fill by label, select, expect text, expect count). Every string below is a JSON literal written by a
// template; no model wrote any code here. Run it with Playwright against the staging shop:
//   npx playwright test --config=<your config with baseURL http://127.0.0.1:8007>
import AxeBuilder from '@axe-core/playwright'
import { expect, test } from '@playwright/test'

// goal: Buy two bags of Ethiopia Guji with WELCOME10, check the cart says 2 items and Total €26.10, then check out as Ada Lovelace, ada@example.test, 1 Rue du Café, Prague and confirm the order.
test("Buy two bags of Ethiopia Guji with WELCOME10, check the cart says 2 items and...", async ({ page }) => {
  // Everything the page logs as an error or throws, and every request answered with an error status.
  const consoleErrors: string[] = []
  page.on('console', (message) => {
    if (message.type() === 'error') consoleErrors.push(message.text())
  })
  page.on('pageerror', error => consoleErrors.push(error.message))
  const failedRequests: string[] = []
  page.on('response', (response) => {
    if (response.status() >= 400) failedRequests.push(`${response.status()} ${new URL(response.url()).pathname}`)
  })

  // step 1: go to /
  await page.goto("/")
  // step 2: click the button \"Add Ethiopia Guji to cart\"
  await page.getByRole("button", { name: "Add Ethiopia Guji to cart", exact: true }).click()
  // step 3: go to /
  await page.goto("/")
  // step 4: click the button \"Add Ethiopia Guji to cart\"
  await page.getByRole("button", { name: "Add Ethiopia Guji to cart", exact: true }).click()
  // step 5: expect the text \"2 items\"
  await expect(page.getByText("2 items", { exact: false }).first()).toBeVisible()
  // step 6: fill \"Coupon code\"
  await page.getByLabel("Coupon code", { exact: true }).fill("WELCOME10")
  // step 7: click the button \"Apply coupon\"
  await page.getByRole("button", { name: "Apply coupon", exact: true }).click()
  // step 8: expect the text \"Total €26.10\"
  await expect(page.getByText("Total €26.10", { exact: false }).first()).toBeVisible()
  // step 9: go to /checkout
  await page.goto("/checkout")
  // step 10: fill \"Full name\"
  await page.getByLabel("Full name", { exact: true }).fill("Ada Lovelace")
  // step 11: fill \"Email address\"
  await page.getByLabel("Email address", { exact: true }).fill("ada@example.test")
  // step 12: fill \"Street address\"
  await page.getByLabel("Street address", { exact: true }).fill("1 Rue du Café")
  // step 13: fill \"City\"
  await page.getByLabel("City", { exact: true }).fill("Prague")
  // step 14: click the button \"Place order\"
  await page.getByRole("button", { name: "Place order", exact: true }).click()
  // step 15: expect the text \"Thank you!\"
  await expect(page.getByText("Thank you!", { exact: false }).first()).toBeVisible()
  // step 16: expect the text \"is confirmed\"
  await expect(page.getByText("is confirmed", { exact: false }).first()).toBeVisible()

  // The checks code made during the run: accessibility, the console and the requests.
  const axe = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa']).analyze()
  expect(axe.violations.map(violation => violation.id)).toEqual([])
  expect(consoleErrors).toEqual([])
  expect(failedRequests).toEqual([])
})
